Below is a small Flask app using SQLite. Each edit creates a new version; previous versions remain visible. Access requires a shared practice password.

### 1. Save as `app.py`

```python
import hmac
import os
import secrets
import sqlite3
from functools import wraps

from flask import (
    Flask, abort, g, redirect, render_template_string,
    request, session, url_for,
)

app = Flask(__name__)

# Both values must be set before starting the app.
app.secret_key = os.environ["SECRET_KEY"]
PRACTICE_PASSWORD = os.environ["PRACTICE_PASSWORD"]
DATABASE = os.environ.get("DATABASE_PATH", "physio.db")

app.config.update(
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Set HTTPS=1 when serving over HTTPS.
    SESSION_COOKIE_SECURE=os.environ.get("HTTPS") == "1",
)


def db():
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(error):
    connection = g.pop("db", None)
    if connection is not None:
        connection.close()


def init_db():
    with app.app_context():
        db().executescript("""
            CREATE TABLE IF NOT EXISTS patients (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS notes (
                id INTEGER PRIMARY KEY,
                patient_id INTEGER NOT NULL REFERENCES patients(id),
                visit_date TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS note_versions (
                id INTEGER PRIMARY KEY,
                note_id INTEGER NOT NULL REFERENCES notes(id),
                body TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
        """)
        db().commit()


def csrf_token():
    if "csrf" not in session:
        session["csrf"] = secrets.token_urlsafe(32)
    return session["csrf"]


app.jinja_env.globals["csrf_token"] = csrf_token


@app.before_request
def check_csrf():
    if request.method == "POST":
        expected = session.get("csrf", "")
        supplied = request.form.get("csrf", "")
        if not expected or not hmac.compare_digest(expected, supplied):
            abort(400, "Invalid form token. Refresh and try again.")


def login_required(view):
    @wraps(view)
    def wrapped(*args, **kwargs):
        if not session.get("logged_in"):
            return redirect(url_for("login"))
        return view(*args, **kwargs)
    return wrapped


BASE = """
<!doctype html>
<html>
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Physio notes</title>
  <style>
    body { font: 16px sans-serif; max-width: 800px; margin: 2rem auto;
           padding: 0 1rem; line-height: 1.5; }
    input, textarea, button { font: inherit; padding: .4rem; }
    textarea { width: 100%; box-sizing: border-box; }
    article { border: 1px solid #ccc; padding: 1rem; margin: 1rem 0; }
    pre { white-space: pre-wrap; font: inherit; overflow-wrap: anywhere; }
    .error { color: #a00; }
  </style>
</head>
<body>
  <h1>Physio notes</h1>
  {% if session.get('logged_in') %}
    <p><a href="{{ url_for('index') }}">Patients</a></p>
    <form method="post" action="{{ url_for('logout') }}">
      <input type="hidden" name="csrf" value="{{ csrf_token() }}">
      <button>Log out</button>
    </form>
  {% endif %}
  {{ content|safe }}
</body>
</html>
"""


def page(template, **kwargs):
    # The inner template is rendered with autoescaping before insertion.
    content = render_template_string(template, **kwargs)
    return render_template_string(BASE, content=content)


@app.route("/login", methods=["GET", "POST"])
def login():
    error = None
    if request.method == "POST":
        password = request.form.get("password", "")
        if hmac.compare_digest(password.encode(), PRACTICE_PASSWORD.encode()):
            session.clear()
            session["logged_in"] = True
            return redirect(url_for("index"))
        error = "Incorrect password."
    return page("""
        <h2>Log in</h2>
        {% if error %}<p class="error">{{ error }}</p>{% endif %}
        <form method="post">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <label>Password <input name="password" type="password" required></label>
          <button>Log in</button>
        </form>
    """, error=error)


@app.post("/logout")
@login_required
def logout():
    session.clear()
    return redirect(url_for("login"))


@app.route("/", methods=["GET", "POST"])
@login_required
def index():
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        if not name:
            abort(400, "Patient name is required.")
        db().execute("INSERT INTO patients (name) VALUES (?)", (name,))
        db().commit()
        return redirect(url_for("index"))

    patients = db().execute(
        "SELECT id, name FROM patients ORDER BY name, id"
    ).fetchall()
    return page("""
        <h2>Patients</h2>
        <form method="post">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <label>Name <input name="name" required></label>
          <button>Add patient</button>
        </form>
        <ul>
          {% for patient in patients %}
            <li><a href="{{ url_for('patient', patient_id=patient.id) }}">
              {{ patient.name }}</a></li>
          {% else %}
            <li>No patients yet.</li>
          {% endfor %}
        </ul>
    """, patients=patients)


@app.route("/patient/<int:patient_id>", methods=["GET", "POST"])
@login_required
def patient(patient_id):
    person = db().execute(
        "SELECT * FROM patients WHERE id = ?", (patient_id,)
    ).fetchone()
    if person is None:
        abort(404)

    if request.method == "POST":
        visit_date = request.form.get("visit_date", "").strip()
        body = request.form.get("body", "").strip()
        if not visit_date or not body:
            abort(400, "Visit date and note are required.")
        with db():
            cursor = db().execute(
                "INSERT INTO notes (patient_id, visit_date) VALUES (?, ?)",
                (patient_id, visit_date),
            )
            db().execute(
                "INSERT INTO note_versions (note_id, body) VALUES (?, ?)",
                (cursor.lastrowid, body),
            )
        return redirect(url_for("patient", patient_id=patient_id))

    notes = db().execute(
        "SELECT * FROM notes WHERE patient_id = ? ORDER BY visit_date DESC, id DESC",
        (patient_id,),
    ).fetchall()
    versions = {
        note["id"]: db().execute(
            "SELECT * FROM note_versions WHERE note_id = ? ORDER BY id DESC",
            (note["id"],),
        ).fetchall()
        for note in notes
    }
    return page("""
        <h2>{{ person.name }}</h2>
        <h3>New visit note</h3>
        <form method="post">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <label>Visit date <input type="date" name="visit_date" required></label>
          <p><textarea name="body" rows="5" required></textarea></p>
          <button>Save note</button>
        </form>

        <h3>Visit history</h3>
        {% for note in notes %}
          <article>
            <h4>{{ note.visit_date }}</h4>
            {% for version in versions[note.id] %}
              <details {% if loop.first %}open{% endif %}>
                <summary>
                  {{ "Current version" if loop.first else "Previous version" }}
                  — saved {{ version.created_at }} UTC
                </summary>
                <pre>{{ version.body }}</pre>
              </details>
            {% endfor %}
            <h4>Save a new version</h4>
            <form method="post" action="{{ url_for('edit_note', note_id=note.id) }}">
              <input type="hidden" name="csrf" value="{{ csrf_token() }}">
              <textarea name="body" rows="5" required>{{ versions[note.id][0].body }}</textarea>
              <button>Save new version</button>
            </form>
          </article>
        {% else %}
          <p>No visit notes yet.</p>
        {% endfor %}
    """, person=person, notes=notes, versions=versions)


@app.post("/note/<int:note_id>/edit")
@login_required
def edit_note(note_id):
    note = db().execute(
        "SELECT * FROM notes WHERE id = ?", (note_id,)
    ).fetchone()
    if note is None:
        abort(404)
    body = request.form.get("body", "").strip()
    if not body:
        abort(400, "Note cannot be empty.")
    db().execute(
        "INSERT INTO note_versions (note_id, body) VALUES (?, ?)",
        (note_id, body),
    )
    db().commit()
    return redirect(url_for("patient", patient_id=note["patient_id"]))


init_db()

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000, debug=False)
```

### 2. Run it

```bash
pip install flask
export SECRET_KEY="$(python -c 'import secrets; print(secrets.token_hex(32))')"
export PRACTICE_PASSWORD="choose-a-strong-password"
python app.py
```

Open `http://127.0.0.1:5000`. Notes persist in `physio.db` in the working directory. Keep a secure backup of that file.

**Before using real patient information:** this is a local prototype, not a production-ready health-record system. It needs safeguards such as HTTPS, individual user accounts, login rate limiting, audit logging, encrypted storage and backups, and an assessment against applicable privacy and health-record requirements. The app has no delete or overwrite controls, but someone with direct database access can still change its records.

